function getImgList(){
var jp = "src=\"(.*.ibuka.cn\/pics\/.*?)0001.jpg";
var p = "pcount = (.*);";
var jpgstr = html.match(jp)[1];
var mp = html.match(p)[1];
var piclist = new Array(mp); 
for (var i = 0; i < mp; i++) {         
piclist[i] = jpgstr+(Array(4).join('0') + (i+1)).slice(-4)+".jpg";
}
return piclist; 
}

